#include &lt;hip/hip_runtime.h&gt;

__global__ void fused_conv_tanh_scale_bias_kernel(
    const float* input,
    const float* weight,
    const float* c_bias,
    float scale,
    const float* a_bias,
    float* output,
    int B, int Cin, int Cout,
    int Hin, int Win, int Hout, int Wout,
    int Kh, int Kw
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * Cout * Hout * Wout;
    if (idx &gt;= total) return;
    int b = idx / (Cout * Hout * Wout);
    int remaining = idx % (Cout * Hout * Wout);
    int cout_ = remaining / (Hout * Wout);
    int oh = (remaining / Wout) % Hout;
    int ow = remaining % Wout;
    float acc = c_bias[cout_];
    for (int ci = 0; ci &lt; Cin; ++ci) {
        for (int kh = 0; kh &lt; Kh; ++kh) {
            for (int kw = 0; kw &lt; Kw; ++kw) {
                int h = oh + kh;
                int w = ow + kw;
                float in_val = input[ ((b * Cin + ci) * Hin + h) * Win + w ];
                float w_val = weight[ ((cout_ * Cin + ci) * Kh + kh) * Kw + kw ];
                acc += in_val * w_val;
            }
        }
    }
    float act = tanhf(acc);
    int out_idx = ((b * Cout + cout_) * Hout + oh) * Wout + ow;
    output[out_idx] = act * scale + a_bias[cout_];
}

torch::Tensor fused_conv_tanh_scale_bias_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor c_bias,
    float scale,
    torch::Tensor a_bias
) {
    auto input_c = input.contiguous();
    auto weight_c = weight.contiguous();
    auto c_bias_c = c_bias.contiguous();
    auto a_bias_c = a_bias.contiguous();
    auto desc = input_c.sizes();
    int64_t B = desc[0];
    int64_t Cin = desc[1];
    int64_t Hin = desc[2];
    int64_t Win = desc[3];
    desc = weight_c.sizes();
    int64_t Cout = desc[0];
    int64_t Kh = desc[2];
    int64_t Kw = desc[3];
    int64_t Hout = Hin - Kh + 1;
    int64_t Wout = Win - Kw + 1;
    torch::Tensor out = torch::zeros({B, Cout, Hout, Wout}, input_c.options());
    int64_t total = B * Cout * Hout * Wout;
    const int bsize = 256;
    const int64_t nblocks = (total + bsize - 1) / bsize;
    fused_conv_tanh_scale_bias_kernel&lt;&lt;&lt;nblocks, bsize&gt;&gt;&gt;(
        input_c.data_ptr&lt;float&gt;(),
        weight_c.data_ptr&lt;float&gt;(),
        c_bias_c.data_ptr&lt;float&gt;(),
        scale,
        a_bias_c.data_ptr&lt;float&gt;(),
        out.data_ptr&lt;float&gt;(),
        (int)B, (int)Cin, (int)Cout,
        (int)Hin, (int)Win, (int)Hout, (int)Wout,
        (int)Kh, (int)Kw
    );
    return out;
}
"""

