#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

__global__ void fused_conv_tanh_scale_bias_kernel(
    const float* input,
    const float* weight,
    const float* c_bias,
    float scale,
    const float* a_bias,
    float* output,
    int B, int Cin, int Cout,
    int Hin, int Win, int Hout, int Wout,
    int Kh, int Kw
) {
    constexpr int TILE_OH = 16;
    constexpr int TILE_OW = 16;
    constexpr int IH_PAD = 20;
    constexpr int IW_PAD = 20;
    constexpr int MAX_CIN = 8;
    __shared__ float s_input[MAX_CIN * IH_PAD * IW_PAD];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * blockDim.x + tx;
    int tile_oh = blockIdx.y;
    int tile_ow = blockIdx.x;
    int bcid = blockIdx.z;
    int b = bcid / Cout;
    int cout_ = bcid % Cout;
    int oh = tile_oh * TILE_OH + ty;
    int ow = tile_ow * TILE_OW + tx;

    int h_base = tile_oh * TILE_OH;
    int w_base = tile_ow * TILE_OW;
    bool valid = (oh < Hout && ow < Wout);
    float acc = 0.0f;
    if (valid) {
        acc = c_bias[cout_];
    }

    // load all input tiles for all ci once
    int sh_sp_size = IH_PAD * IW_PAD;
    int sh_size = MAX_CIN * sh_sp_size;
    for (int i = tid; i < sh_size; i += blockDim.x * blockDim.y) {
        int ci_sh = i / sh_sp_size;
        int rem = i % sh_sp_size;
        int lh = rem / IW_PAD;
        int lw = rem % IW_PAD;
        int gh = h_base + lh;
        int gw = w_base + lw;
        float val = 0.0f;
        if (ci_sh < Cin && gh >= 0 && gh < Hin && gw >= 0 && gw < Win) {
            val = input[((b * Cin + ci_sh) * Hin + gh) * Win + gw];
        }
        s_input[i] = val;
    }
    __syncthreads();

    // compute all ci no sync
    if (valid) {
        for (int ci = 0; ci < Cin; ++ci) {
            int off = ci * sh_sp_size;
            #pragma unroll
            for (int kh = 0; kh < Kh; ++kh) {
                #pragma unroll
                for (int kw = 0; kw < Kw; ++kw) {
                    int lh = ty + kh;
                    int lw = tx + kw;
                    if (lh < IH_PAD && lw < IW_PAD) {
                        float in_val = s_input[off + lh * IW_PAD + lw];
                        float w_val = weight[((cout_ * Cin + ci) * Kh + kh) * Kw + kw];
                        acc += in_val * w_val;
                    }
                }
            }
        }
        float act = tanhf(acc);
        int out_idx = ((b * Cout + cout_) * Hout + oh) * Wout + ow;
        output[out_idx] = act * scale + a_bias[cout_];
    }
}

torch::Tensor fused_conv_tanh_scale_bias_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor c_bias,
    float scale,
    torch::Tensor a_bias
) {
    auto input_c = input.contiguous();
    auto weight_c = weight.contiguous();
    auto c_bias_c = c_bias.contiguous();
    auto a_bias_c = a_bias.contiguous();
    auto desc = input_c.sizes();
    int64_t B = desc[0];
    int64_t Cin = desc[1];
    int64_t Hin = desc[2];
    int64_t Win = desc[3];
    desc = weight_c.sizes();
    int64_t Cout = desc[0];
    int64_t Kh = desc[2];
    int64_t Kw = desc[3];
    int64_t Hout = Hin - Kh + 1;
    int64_t Wout = Win - Kw + 1;
    torch::Tensor out = torch::zeros({B, Cout, Hout, Wout}, input_c.options());

    constexpr int TILE_OH = 16;
    constexpr int TILE_OW = 16;
    int ntiles_oh = (Hout + TILE_OH - 1) / TILE_OH;
    int ntiles_ow = (Wout + TILE_OW - 1) / TILE_OW;
    dim3 block(TILE_OW, TILE_OH, 1);
    dim3 grid(ntiles_ow, ntiles_oh, static_cast<int>(B * Cout));
    fused_conv_tanh_scale_bias_kernel<<<grid, block>>>(
