        static_cast<int>(B), static_cast<int>(Cin), static_cast<int>(Cout),
        static_cast<int>(Hin), static_cast<int>(Win), static_cast<int>(Hout), static_cast<int>(Wout),
        static_cast<int>(Kh), static_cast<int>(Kw)
    );
    return out;
}
