    int64_t total = B * C * Ph * Pw;
    const int bsize = 256;
    const int64_t nblocks = (total + bsize - 1) / bsize;
    post_pool_kernel<<<nblocks, bsize>>>(
        inp.data_ptr<float>(),
        scale,
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        (int)B, (int)C, (int)H, (int)W, (int)Ph, (int)Pw
    );
